import 'package:flutter/material.dart';void main() {  runApp(const MyApp());}class MyApp extends StatelessWidget {  const MyApp({super.key});  @override  Widget build(BuildContext context) {    return const MaterialApp(      title: 'Simple Calculator',      home: Calculator(),    );  }}class Calculator extends StatefulWidget {  const Calculator({super.key});  @override  State<Calculator> createState() => _CalculatorState();}class _CalculatorState extends State<Calculator> {  final _controller = TextEditingController();  double _num1 = 0;  double _num2 = 0;  String _operation = '';  String _result = '';  void _calculate() {    setState(() {      switch (_operation) {        case '+':          _result = (_num1 + _num2).toString();          break;        case '-':          _result = (_num1 - _num2).toString();          break;        case '*':          _result = (_num1 * _num2).toString();          break;        case '/':          if (_num2 != 0) {            _result = (_num1 / _num2).toString();          } else {            _result = 'Error: Division by zero';          }          break;        default:          _result = '';      }    });  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text('Simple Calculator'),      ),      body: Padding(        padding: const EdgeInsets.all(16.0),        child: Column(          mainAxisAlignment: MainAxisAlignment.spaceBetween,          children: [            TextField(              controller: _controller,              decoration: const InputDecoration(                border: OutlineInputBorder(),                labelText: 'Result',              ),              readOnly: true,            ),            Row(              mainAxisAlignment: MainAxisAlignment.spaceBetween,              children: [                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '7';                    });                  },                  child: const Text('7'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '8';                    });                  },                  child: const Text('8'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '9';                    });                  },                  child: const Text('9'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '/';                    });                  },                  child: const Text('/'),                ),              ],            ),            Row(              mainAxisAlignment: MainAxisAlignment.spaceBetween,              children: [                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '4';                    });                  },                  child: const Text('4'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '5';                    });                  },                  child: const Text('5'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '6';                    });                  },                  child: const Text('6'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '*';                    });                  },                  child: const Text('*'),                ),              ],            ),            Row(              mainAxisAlignment: MainAxisAlignment.spaceBetween,              children: [                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '1';                    });                  },                  child: const Text('1'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '2';                    });                  },                  child: const Text('2'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '3';                    });                  },                  child: const Text('3'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '-';                    });                  },                  child: const Text('-'),                ),              ],            ),            Row(              mainAxisAlignment: MainAxisAlignment.spaceBetween,              children: [                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '0';                    });                  },                  child: const Text('0'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '.';                    });                  },                  child: const Text('.'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '=';                    });                  },                  child: const Text('='),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text += '+';                    });                  },                  child: const Text('+'),                ),              ],            ),            Row(              mainAxisAlignment: MainAxisAlignment.spaceBetween,              children: [                ElevatedButton(                  onPressed: () {                    setState(() {                      _controller.text = '';                      _num1 = 0;                      _num2 = 0;                      _operation = '';                      _result = '';                    });                  },                  child: const Text('Clear'),                ),                ElevatedButton(                  onPressed: () {                    setState(() {                      if (_controller.text.isNotEmpty) {                        _controller.text = _controller.text.substring(0, _controller.text.length - 1);                      }                    });                  },                  child: const Text('Backspace'),                ),                ElevatedButton(                  onPressed: _calculate,                  child: const Text('Calculate'),                ),              ],            ),            Text(_result),          ],        ),      ),    );  }}